const duplicateBtn=$('duplicateBtn'),copyBtn=$('copyBtn'),pasteBtn=$('pasteBtn'),validateBtn=$('validateBtn');
const duplicateSelectedBtn=$('duplicateSelectedBtn'),copySelectedBtn=$('copySelectedBtn');
